import { describe, expect, it } from 'vitest'
import { execFileSync, spawnSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { resume } from '@/content/resume'
import { site } from '@/content/site'

const pdf = 'public/resume.pdf'

// pdftotext -v exits 99 by design, so only a missing binary counts as absent.
function hasPdftotext(): boolean {
  return !spawnSync('pdftotext', ['-v']).error
}

// The PDF is regenerated by hand (npm run resume:pdf). These checks catch a stale or broken one.
describe('resume.pdf', () => {
  it('is a single A4 page', () => {
    const raw = readFileSync(pdf, 'latin1')
    expect(raw.match(/\/Type\s*\/Page[^s]/g)).toHaveLength(1)
  })

  it.skipIf(!hasPdftotext())('reads as text, in order, with the numbers intact', () => {
    const text = execFileSync('pdftotext', [pdf, '-'], { encoding: 'utf8' })
    for (const needle of ['70,000+', 'EXPERIENCE', site.email.toUpperCase(), resume.phone, 'Shockwave']) {
      expect(text).toContain(needle)
    }
    expect(text.indexOf('70,000+')).toBeLessThan(text.indexOf('EXPERIENCE'))
    expect(text.indexOf('EV bookings')).toBeLessThan(text.indexOf('EXPERIENCE'))
  })
})
